-- CIQUAL 2025 (ANSES) - table de composition nutritionnelle des aliments FR
-- Source : https://ciqual.anses.fr/ (licence ouverte Etalab)
-- Sous-ensemble : id, nom, groupe, energie/macros pour 100g (colonnes reglementaires
-- UE 1169/2011 pour l'energie, N x 6.25 pour les proteines - coherent avec un
-- etiquetage nutritionnel standard). Lignes sans valeur macro complete exclues.

create extension if not exists pg_trgm;

create table if not exists ciqual_foods (
  id integer primary key,
  name text not null,
  group_name text,
  kcal_100g numeric not null,
  protein_100g numeric not null,
  carbs_100g numeric not null,
  fat_100g numeric not null
);

create index if not exists ciqual_foods_name_trgm_idx
  on ciqual_foods using gin (name gin_trgm_ops);

alter table ciqual_foods enable row level security;

drop policy if exists "Public read access" on ciqual_foods;
create policy "Public read access"
  on ciqual_foods for select
  to anon, authenticated
  using (true);

create or replace function search_ciqual_food(query text, min_similarity real default 0.2)
returns table (
  id integer,
  name text,
  kcal_100g numeric,
  protein_100g numeric,
  carbs_100g numeric,
  fat_100g numeric,
  similarity real
)
language sql stable
as $$
  select
    ciqual_foods.id,
    ciqual_foods.name,
    ciqual_foods.kcal_100g,
    ciqual_foods.protein_100g,
    ciqual_foods.carbs_100g,
    ciqual_foods.fat_100g,
    similarity(ciqual_foods.name, query) as similarity
  from ciqual_foods
  where similarity(ciqual_foods.name, query) > min_similarity
  order by similarity desc
  limit 1;
$$;

truncate table ciqual_foods;

